<script setup>
const { t, formatDate, formatTime, formatMoney } = useAppI18n()
defineProps({ claim: Object, missions: Array, audit: Array, pending: Boolean, clientDocuments: Array, agentMode: Boolean })
defineEmits(['back', 'plan', 'permit-access', 'accommodate', 'schedule', 'client'])
</script>

<template>
  <section class="claim-detail">
