    <section class="detail-section incident-summary"><p>{{ claim.summaryIsUserContent ? claim.summary : t(claim.summary) }}</p><div class="key-value"><span>{{ t('Flood event') }}</span><strong>{{ formatDate(claim.eventDate || claim.date, { month: 'short' }) }}</strong></div><p>{{ t(claim.address) }}<br>{{ t(claim.addressNote) }}</p></section>
    <section class="detail-section"><h3>{{ t('Why this priority') }}</h3><p>{{ t(claim.priorityReason) }}</p><div class="info-row"><UiIcon name="House" :size="14" /><span>{{ t(claim.situation) }}</span><small>{{ claim.group }}</small></div><p>{{ claim.currentAccommodationIsUserContent ? claim.currentAccommodation : t(claim.currentAccommodation) }}</p></section>
