    <section v-if="!agentMode && claim.id === 'CAT-2026-001'" class="detail-section"><h3>{{ t('Shared client documents') }}</h3><p v-if="!claim.opened">{{ t('This portfolio record is awaiting the client report. It is not a second claim.') }}</p><ul v-else><li v-for="row in clientDocuments" :key="row.id"><span>{{ t(row.title) }}</span><small>{{ t(row.files.length ? 'Received' : 'Missing') }}</small></li></ul><UiButton v-if="claim.opened" class="small" @click="$emit('client')">{{ t('View client claim') }}<UiIcon name="ArrowUpRight" :size="13" /></UiButton></section>
    <section class="detail-section"><h3>{{ t('Missions') }}</h3><p v-if="!missions.length">{{ t('No physical mission has been proposed for this record.') }}</p><div v-for="mission in missions" :key="mission.id" class="mission-item"><strong>{{ t(mission.skill) }}</strong><span>{{ t(mission.status) }}</span><small>{{ mission.provider?.name || t('Provider not assigned') }}</small></div><button v-if="!agentMode && claim.stage !== 4 && claim.access === 'Permitted' && missions.some(mission => mission.status === 'Proposed')" class="text-action" :disabled="pending" @click="$emit('schedule')">{{ t('Schedule accessible missions') }}</button></section>
    <section class="detail-section"><h3>{{ t('Activity timeline') }}</h3><p v-if="!claim.chronology.length">{{ t('Awaiting the client report.') }}</p><div v-for="(entry, index) in [...claim.chronology, ...audit]" :key="`${entry.at}-${index}`" class="activity-entry"><i /><span>{{ t(entry.label) }}<small>{{ formatDate(entry.at, { day: 'numeric', month: 'short', year: undefined }) }} · {{ formatTime(entry.at) }}</small></span></div></section>
    <footer v-if="!agentMode" class="detail-actions"><UiButton v-if="claim.unmetAccommodation" class="small" :disabled="pending" @click="$emit('accommodate')">{{ t('Preview accommodation placement') }}</UiButton><UiButton class="dark" :disabled="pending || claim.stage === 4" @click="$emit('plan')">{{ t('Plan assistance') }}<UiIcon name="ChevronRight" :size="14" /></UiButton><p>{{ t('Review access, capacity and household requirements before confirming assistance.') }}</p></footer>
  </section>
